-- One row per extension ↔ Telegram chat link. link_id is a random 128-bit
-- secret generated by the extension; nothing else about the user is stored.
CREATE TABLE links (
  link_id TEXT PRIMARY KEY,
  chat_id INTEGER NOT NULL,
  created_at INTEGER NOT NULL,
  last_heartbeat INTEGER,
  armed INTEGER NOT NULL DEFAULT 0,
  deadman_sent INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX links_chat ON links (chat_id);
CREATE INDEX links_deadman ON links (armed, deadman_sent, last_heartbeat);

-- Per-link, per-minute message counter (rate limiting).
CREATE TABLE rate (
  link_id TEXT NOT NULL,
  minute INTEGER NOT NULL,
  n INTEGER NOT NULL,
  PRIMARY KEY (link_id, minute)
);
